import base64
import binascii

from flask import Blueprint, jsonify, request

from src.api.errors import problem

bp = Blueprint("invoices", __name__)

_INVOICES = {}

DEFAULT_PAGE_SIZE = 50
MAX_PAGE_SIZE = 250


def _money(cents, ccy="USD"):
    return {"minor": cents, "ccy": ccy}


def _encode_cursor(invoice_id):
    return base64.urlsafe_b64encode(invoice_id.encode()).decode()


def _decode_cursor(cursor):
    return base64.urlsafe_b64decode(cursor.encode()).decode()


@bp.get("/invoices/<invoice_id>")
def get_invoice(invoice_id):
    invoice = _INVOICES.get(invoice_id)
    return jsonify(invoice.__dict__)


@bp.get("/customers/<customer_id>/invoices")
def list_customer_invoices(customer_id):
    page_size = request.args.get("page_size", DEFAULT_PAGE_SIZE, type=int)
    if page_size is None or not 1 <= page_size <= MAX_PAGE_SIZE:
        return problem(400, "Invalid page_size", f"page_size must be an integer between 1 and {MAX_PAGE_SIZE}")

    after = None
    cursor = request.args.get("cursor")
    if cursor:
        try:
            after = _decode_cursor(cursor)
        except (binascii.Error, UnicodeDecodeError):
            return problem(400, "Invalid cursor", "cursor is not a value returned by this endpoint")

    invoices = sorted(
        (inv for inv in _INVOICES.values() if inv.customer_id == customer_id),
        key=lambda inv: inv.id,
    )
    if after is not None:
        invoices = [inv for inv in invoices if inv.id > after]

    page = invoices[:page_size]
    has_more = len(invoices) > page_size
    return jsonify({
        "items": [
            {
                "id": inv.id,
                "customer_id": inv.customer_id,
                "subtotal": _money(inv.subtotal_cents),
                "tax": _money(inv.tax_cents),
                "total": _money(inv.subtotal_cents + inv.tax_cents),
            }
            for inv in page
        ],
        "next_cursor": _encode_cursor(page[-1].id) if has_more else None,
    })

